PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE comments (
    id INTEGER PRIMARY KEY NOT NULL,
    author TEXT NOT NULL,
    content TEXT NOT NULL
);
CREATE TABLE tb_emprestimo (   id_emprestimo INTEGER PRIMARY KEY AUTOINCREMENT,   nome TEXT NOT NULL,   email TEXT NOT NULL,   data_reserva TEXT NOT NULL,   unidade TEXT NOT NULL,   nome_produto TEXT,   quant INTEGER,   destinatario TEXT,   processamento INTEGER NOT NULL DEFAULT 0,   unidade_natal TEXT,   unidade_atual varchar(100) not null, data_devolucao date null, data_postagem date null, motivo varchar(500) null, produto_codigo varchar (15) not null, prioridade TEXT CHECK(prioridade IN ('alto', 'intermediário', 'baixo')), aprovacao int default 0);
CREATE TABLE tb_estoque (   id_estoque INTEGER PRIMARY KEY AUTOINCREMENT,   nome TEXT NOT NULL,   codigo TEXT NOT NULL,   descricao TEXT NOT NULL,   descricao_detalhada TEXT,   cor TEXT,   quant INTEGER NOT NULL,   uni_intermediarias TEXT,   marca_ref TEXT,   uni_natal TEXT NOT NULL,   pedido TEXT NOT NULL DEFAULT '0',   foto TEXT , uni_atual varchar(150) null, produto_retornado int null default 0);
CREATE TABLE tb_usuarios (   id INTEGER PRIMARY KEY AUTOINCREMENT,   usuario TEXT NOT NULL,   senha TEXT NOT NULL,   nivel_conta INTEGER NOT NULL,   unidade TEXT NOT NULL );
CREATE TABLE tb_carrinho (
    id_carrinho INTEGER PRIMARY KEY AUTOINCREMENT,
    produto VARCHAR(100) NOT NULL,
    quantidade INTEGER DEFAULT 1,
    usuario VARCHAR(64) NOT NULL,
    carrinho INTEGER DEFAULT 1,
    FOREIGN KEY (produto) REFERENCES tb_estoque(nome) ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY (usuario) REFERENCES tb_usuarios(usuario) ON UPDATE CASCADE ON DELETE CASCADE
);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX idx_usuario_unico ON tb_usuarios(usuario);
CREATE UNIQUE INDEX idx_produto_unico ON tb_estoque(nome);
